-- 0099: реестр параметров причин знает COST_REQUIRED [Р-131, шаг 27]
-- Причина «репрайсинг не включается без себестоимости» — такой же параметр причины, как остальные: база хранит её объявление,
-- иначе слепок с ней отклоняется (0066, 0070). Список причин у COST_REQUIRED — тот же, что у пола маржи: себестоимость не объявлена
-- или объявлена, но не переводится в валюту единицы записи [Р-61].

CREATE OR REPLACE FUNCTION security.eternal_param_keys() RETURNS jsonb
